{
  "schema_version": "optomind.writer_candidates.payload.v1",
  "chapter_id": "Ch2",
  "language": "zh",
  "chapter_frame": {
    "chapter_title": "微生物调节 ICI 疗效的免疫学机制",
    "chapter_purpose": "帮助读者建立“微生物信号→先天识别→适应性启动→髓系/屏障重塑”的机制链条认知，明确区分动物模型中的因果发现与人类队列中的相关性证据，并理解不同实体瘤类型中机制表达的异质性，为后续代谢物专论（Ch3）与临床转化（Ch5）奠定生物学基础。",
    "chapter_scope": "肠道微生物组并非仅作为旁观者，而是通过模式识别受体（PRRs）触发先天免疫识别、介导抗原交叉反应以启动适应性免疫、以及重塑髓系细胞稳态与肠道屏障完整性，系统性驱动抗肿瘤免疫激活；然而，这些机制的临床外推受限于模型系统差异与肿瘤类型特异性，需严格区分临床前因果证据与人类队列的观察性关联。",
    "chapter_thesis": "肠道微生物组并非仅作为旁观者，而是通过模式识别受体（PRRs）触发先天免疫识别、介导抗原交叉反应以启动适应性免疫、以及重塑髓系细胞稳态与肠道屏障完整性，系统性驱动抗肿瘤免疫激活；然而，这些机制的临床外推受限于模型系统差异与肿瘤类型特异性，需严格区分临床前因果证据与人类队列的观察性关联。",
    "chapter_argument": "肠道微生物组并非仅作为旁观者，而是通过模式识别受体（PRRs）触发先天免疫识别、介导抗原交叉反应以启动适应性免疫、以及重塑髓系细胞稳态与肠道屏障完整性，系统性驱动抗肿瘤免疫激活；然而，这些机制的临床外推受限于模型系统差异与肿瘤类型特异性，需严格区分临床前因果证据与人类队列的观察性关联。",
    "reader_objective": "帮助读者建立“微生物信号→先天识别→适应性启动→髓系/屏障重塑”的机制链条认知，明确区分动物模型中的因果发现与人类队列中的相关性证据，并理解不同实体瘤类型中机制表达的异质性，为后续代谢物专论（Ch3）与临床转化（Ch5）奠定生物学基础。",
    "research_question": "How does the gut microbiome modulate the efficacy of immune checkpoint inhibitors in solid tumours, and what mechanisms mediate that effect?",
    "review_argument": "肠道微生物组通过分类学特征、代谢产物及免疫通路调节实体瘤患者对 ICI 的临床疗效，但证据强度因肿瘤类型、研究设计及干预策略而异。观察性关联证据在黑色素瘤中最强，NSCLC 和 RCC 次之，但关联不等于因果。机制证据主要来自动物模型，人类验证有限，特别是肿瘤微环境内代谢物浓度数据缺失（如肌苷仅有血浆数据）。干预策略在初治人群中显示希望（FMT-LUMINate ORR 75-80%），但在难治人群中效果有限（MITRIC ORR 0%），且安全性受 ICI 方案调节（Prevotella 相关心肌炎仅在双 ICI 背景下出现）。目前缺乏 Phase III RCT 证据支持微生物干预的常规临床应用，未来研究需解决标准化、因果推断及人群分层问题。",
    "shared_scope": {
      "statement": "本综述聚焦于实体瘤（黑色素瘤、非小细胞肺癌、肾细胞癌、结直肠癌等）患者接受免疫检查点抑制剂（PD-1/PD-L1、CTLA-4 抑制剂）治疗期间，肠道微生物组对治疗疗效（ORR、PFS、OS）及毒性（irAEs）的调节作用。涵盖观察性关联证据（区分回顾性与前瞻性队列）、因果机制解析（免疫细胞、分子通路、代谢物）、外部干扰因素（抗生素、PPI、饮食）及微生物干预策略（FMT、益生菌、工程菌）的临床试验数据。明确排除血液系统恶性肿瘤及非免疫治疗背景下的微生物组研究（除非用于机制对比）。严格区分肠道微生物组与肿瘤内微生物组的作用边界。证据等级标注明确：观察性关联不推断因果，干预试验区分 I/II 期与 III 期，代谢物数据区分血浆与肿瘤组织浓度。"
    },
    "review_argument_status": "calibrated",
    "review_argument_source": "whole_plan_improvement"
  },
  "editable_task_ids": [
    "Ch2_U01::Ch2_U01_P01",
    "Ch2_U01::Ch2_U01_P02",
    "Ch2_U01::Ch2_U01_P03"
  ],
  "units": [
    {
      "unit_id": "Ch2_U01",
      "focus": "先天免疫识别与树突状细胞（DC）的抗原呈递启动：微生物分子结构（如六酰化 LPS）与 PRR/STING 通路决定 DC 成熟、迁移和 CD8+ T 细胞启动，但人类证据主要为宏基因组关联、临床干预伴随观察或肿瘤内微生物生态相关数据。",
      "paragraph_tasks": [
        {
          "paragraph_id": "Ch2_U01_P01",
          "point": "先天识别不是“有菌即激活”，而受微生物分子结构与受体语境调节。",
          "development": "以六酰化 LPS 与五酰化 LPS 的差异为核心，说明 LPS 酰化状态如何通过 TLR4/NF-κB 改变 DC/髓系细胞激活及抗 PD-1 疗效；同时引入 MAMPs 经 TLR/NOD2 刺激抗原呈递细胞、促进 Th1 极化的综述框架，并用 CRC 综述中 TLR4/NLRP3 与 Fn/cGAS-IFN-β 的语境差异提示同一通路在不同肿瘤或微生物背景下可能产生不同方向。",
          "source_uses": [
            {
              "source_handle": "P0080",
              "role": "主论据",
              "use": "提供六酰化 LPS 经 TLR4/NF-κB 增强抗 PD-1 疗效、五酰化 LPS 拮抗的具体分子案例，并配套人类黑色素瘤宏基因组关联与 MC38 小鼠因果验证。"
            },
            {
              "source_handle": "P0309",
              "role": "背景",
              "use": "提供 MAMPs（如鞭毛蛋白、肽聚糖）经 TLR/NOD2 刺激 APC、促进 Th1 极化和抗原呈递的跨免疫干预框架。"
            },
            {
              "source_handle": "P0028",
              "role": "局限",
              "use": "提供 CRC 背景下 TLR4/NLRP3、Fn 琥珀酸抑制 cGAS-IFN-β、B. fragilis 多糖与 CTLA-4 协同等语境化案例，防止将 PRR 通路写成单向促免疫。"
            }
          ],
          "carried_over": true,
          "point_changed_from_brief": false,
          "source_briefs": [
            "Ch2_U01_P01"
          ],
          "source_brief_details": [
            {
              "paragraph_id": "Ch2_U01_P01",
              "unit_id": "Ch2_U01",
              "ordinal": 1,
              "point": "先天识别不是“有菌即激活”，而受微生物分子结构与受体语境调节。",
              "development": "以六酰化 LPS 与五酰化 LPS 的差异为核心，说明 LPS 酰化状态如何通过 TLR4/NF-κB 改变 DC/髓系细胞激活及抗 PD-1 疗效；同时引入 MAMPs 经 TLR/NOD2 刺激抗原呈递细胞、促进 Th1 极化的综述框架，并用 CRC 综述中 TLR4/NLRP3 与 Fn/cGAS-IFN-β 的语境差异提示同一通路在不同肿瘤或微生物背景下可能产生不同方向。",
              "source_handles": [
                "P0080",
                "P0309",
                "P0028"
              ]
            }
          ]
        },
        {
          "paragraph_id": "Ch2_U01_P02",
          "point": "DC 亚群成熟、迁移与 STING/IFN-β 轴是微生物信号转化为 CD8+ T 细胞启动的关键节点。",
          "development": "以 P0114 的 Ruminococcaceae 菌株为例，说明 TLR 刺激如何经 IRF8 驱动 CD103+ DC 分化并向肿瘤及引流淋巴结迁移，进而通过 NFATc1 增强 CD8+ T 细胞激活和 PD-1 表达；再以综述中的临床前证据补充口服乳酸杆菌、LGG、BF839 或 c-di-AMP 等通过 cGAS-STING/IFN-β 增强 DC 功能和 CD8+ T 细胞浸润，但需明确这些多为动物或综述归纳证据，不能直接外推为人类普适机制。",
          "source_uses": [
            {
              "source_handle": "P0114",
              "role": "主论据",
              "use": "提供响应者来源 Ruminococcaceae 菌株通过 TLR/IRF8 驱动 CD103+ DC 分化、迁移并增强 CD8+ T 细胞激活的 DC 亚群特异性机制。"
            },
            {
              "source_handle": "P0132",
              "role": "背景",
              "use": "提供综述层面的临床前证据，说明口服乳酸杆菌等可通过 cGAS/STING 诱导 DC IFN-β 并促进 CD8+ T 细胞浸润。"
            },
            {
              "source_handle": "P0333",
              "role": "背景",
              "use": "提供 LGG、BF839、Akkermansia 等通过 cGAS-STING 或其他通路调节 DC 与 CD8+ T 细胞的综述性机制图谱。"
            },
            {
              "source_handle": "P0309",
              "role": "背景",
              "use": "补充 MAMPs 经 TLR/NOD2 刺激 APC、促进 Th1 极化的跨免疫干预框架，与 STING 通路形成互补。"
            }
          ],
          "carried_over": true,
          "point_changed_from_brief": false,
          "source_briefs": [
            "Ch2_U01_P02"
